(function(){
'use strict';
const KEY='nawaf-hq-v5';
let running=false,lastCheck=0,lastOpenedTaskId='';
const $=s=>document.querySelector(s);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated'))}
function emp(s,id){return (s.employees||[]).find(e=>e.id===id)}
function office(){return window.NawafHQ3D||null}
function route(id,status){try{office()?.routeEmployee?.(id,status)}catch{}}
function lifecycle(type,detail){window.dispatchEvent(new CustomEvent('nawaf:agent-lifecycle',{detail:{type,...detail}}))}
function syncOfficeForTask(task,state){if(!task)return;const e=emp(state,task.employeeId);const status=task.status||e?.status||'READY';route(task.employeeId,status);if(status==='REVIEWING')office()?.review?.();if(status==='WAITING_FOR_NAWAF')office()?.mode?.('nawaf')}
async function cloudReady(){try{if(window.HQCloudReady)await window.HQCloudReady;return !!window.HQCloud}catch{return false}}
async function pull(){if(await cloudReady()){try{return await window.HQCloud.pull()}catch{}}return false}
async function flush(){if(await cloudReady()){try{return await window.HQCloud.push()}catch{}}return false}
async function health(){try{const r=await fetch('/api/gemini',{cache:'no-store'});const j=await r.json();return !!(r.ok&&j.configured)}catch{return false}}
function showNotice(text,type='ok'){let n=$('#agent-notice');if(!n){n=document.createElement('div');n.id='agent-notice';n.style.cssText='position:fixed;left:50%;top:16px;transform:translateX(-50%);z-index:10000;max-width:min(780px,94vw);padding:10px 14px;border-radius:12px;background:#0d1520;border:1px solid #ffffff1a;color:#eef3f8;font:600 12px system-ui;box-shadow:0 14px 40px #0008';document.body.appendChild(n)}n.textContent=text;n.style.borderColor=type==='wait'?'#ffb46355':'#67d69a55';clearTimeout(showNotice.t);showNotice.t=setTimeout(()=>n.remove(),9000)}
async function invokeWorker(taskId='',batch=false,taskIds=[]){const state=read();const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),260000);try{const r=await fetch('/api/worker',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({taskId,state,batch,taskIds}),cache:'no-store',signal:controller.signal});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||j.detail||('HTTP_'+r.status));if(j.state&&typeof j.state==='object')write(j.state);return j}finally{clearTimeout(timer)}}
async function runTask(taskId){if(running)return null;running=true;renderBadge();let result=null;try{await pull();let s=read(),t=(s.tasks||[]).find(x=>x.id===taskId);if(!t){showNotice('المهمة غير موجودة.','wait');return null}if(!s.companyStarted){showNotice('ابدأ الشركة أولاً ثم شغّل الموظفين.','wait');return null}t.status='WORKING';t.progress=0;t.lastRunAt=new Date().toISOString();delete t.blockedReason;const e=emp(s,t.employeeId);if(e){e.status='WORKING';e.task=t.title}write(s);route(t.employeeId,'WORKING');lifecycle('started',{taskId:t.id,employeeId:t.employeeId,title:t.title});renderBadge();showNotice(`بدأ تنفيذ حقيقي بواسطة ${e?.name||'الموظف'}: ${t.title}`,'ok');const ok=await health();if(!ok)throw new Error('محرك AI غير متصل');result=await invokeWorker(taskId);await flush();const latestState=read(),latest=(latestState.tasks||[]).find(x=>x.id===taskId)||t;syncOfficeForTask(latest,latestState);lifecycle('finished',{taskId:latest.id,employeeId:latest.employeeId,title:latest.title,status:latest.status,progress:latest.progress||0,result:latest.aiResult||null});if(latest.status==='COMPLETED')showNotice(`${emp(latestState,latest.employeeId)?.name||'الموظف'} أكمل المهمة وحُفظت الأدلة.`,'ok');else if(latest.status==='WAITING_FOR_NAWAF')showNotice('التنفيذ توقف لأنه يحتاج قرارًا أو دليلًا إضافيًا.','wait');else showNotice('تم تحديث حالة التنفيذ الحقيقية.','ok');window.dispatchEvent(new CustomEvent('nawaf:state-updated'));renderBadge();decorateTasks();return result}catch(err){let s=read(),t=(s.tasks||[]).find(x=>x.id===taskId);if(t){t.status='READY';t.progress=0;t.blockedReason=err?.name==='AbortError'?'انتهت مهلة التنفيذ':String(err.message||err);const e=emp(s,t.employeeId);if(e){e.status='READY';e.task=''}write(s);route(t.employeeId,'READY');lifecycle('failed',{taskId:t.id,employeeId:t.employeeId,title:t.title,error:t.blockedReason})}showNotice('تعذر تشغيل الموظف: '+(err?.name==='AbortError'?'انتهت مهلة التنفيذ':String(err.message||err)),'wait');return null}finally{running=false;renderBadge()}}
async function runNext(){if(running)return null;await pull();let s=read();const ready=(s.tasks||[]).filter(x=>x.status==='READY').slice(0,3);if(!ready.length){showNotice('ما فيه مهام جاهزة للتنفيذ الآن.','ok');return null}running=true;ready.forEach(t=>{t.status='WORKING';t.progress=0;t.lastRunAt=new Date().toISOString();delete t.blockedReason;const e=emp(s,t.employeeId);if(e){e.status='WORKING';e.task=t.title}route(t.employeeId,'WORKING');lifecycle('started',{taskId:t.id,employeeId:t.employeeId,title:t.title})});write(s);renderBadge();showNotice(`بدأ تنفيذ حقيقي لـ ${ready.length} مهمة`,'ok');try{if(!await health())throw new Error('محرك AI غير متصل');const j=await invokeWorker('',true,ready.map(t=>t.id));await flush();const latest=read();ready.forEach(t=>{const now=(latest.tasks||[]).find(x=>x.id===t.id);if(now){syncOfficeForTask(now,latest);lifecycle('finished',{taskId:now.id,employeeId:now.employeeId,title:now.title,status:now.status,progress:now.progress||0,result:now.aiResult||null})}});window.dispatchEvent(new CustomEvent('nawaf:state-updated'));showNotice(`انتهى تشغيل ${j.processed||0} مهمة بنتائج حقيقية.`,'ok');return j}catch(err){await pull();const latest=read();ready.forEach(t=>{const now=(latest.tasks||[]).find(x=>x.id===t.id)||t;route(now.employeeId,now.status||'READY');lifecycle('failed',{taskId:now.id,employeeId:now.employeeId,title:now.title,error:String(err.message||err)})});showNotice('تعذر تشغيل الموظفين: '+String(err.message||err),'wait');return null}finally{running=false;renderBadge()}}
function renderBadge(){const a=$('.hero .actions');if(!a)return;let b=$('#agent-run-next');if(!b){b=document.createElement('button');b.id='agent-run-next';b.type='button';b.className='soft';b.onclick=runNext;a.prepend(b)}const s=read(),ready=(s.tasks||[]).filter(t=>t.status==='READY').length,working=(s.tasks||[]).filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length;b.textContent=running||working?`⚙ تنفيذ حقيقي (${Math.max(working,1)})`:`⚡ شغّل الموظفين (${ready})`;b.disabled=running}
function decorateTasks(){document.querySelectorAll('[data-task]').forEach(btn=>{const id=btn.dataset.task,row=btn.closest('.item');if(!row||row.querySelector('[data-agent-run]'))return;const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;const r=document.createElement('button');r.type='button';r.className='soft';r.dataset.agentRun=id;r.textContent=t.status==='READY'?'تشغيل فعلي':'تشغيل من جديد';r.style.padding='7px 9px';r.onclick=e=>{e.preventDefault();e.stopPropagation();runTask(id)};row.appendChild(r)})}
function decorateTaskModal(){const d=$('#dialog');const f=d?.querySelector('form#f');if(!d||!f||!lastOpenedTaskId||d.querySelector('#save-run-task'))return;const h=d.querySelector('h2')?.textContent||'';if(!h.includes('تعديل المهمة'))return;const actions=f.querySelector('.modal-actions');if(!actions)return;const b=document.createElement('button');b.id='save-run-task';b.type='button';b.className='primary';b.textContent='▶ حفظ وتشغيل فعلي';b.onclick=()=>{const status=f.querySelector('[name="status"]');if(status)status.value='READY';const id=lastOpenedTaskId;f.requestSubmit();setTimeout(()=>runTask(id),650)};actions.appendChild(b)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-task]');if(t)lastOpenedTaskId=t.dataset.task||''},true);
const mo=new MutationObserver(()=>decorateTaskModal());mo.observe(document.documentElement,{subtree:true,childList:true});
async function heartbeat(){if(Date.now()-lastCheck<2000||running)return;lastCheck=Date.now();await pull();renderBadge();const s=read();(s.tasks||[]).filter(t=>['WORKING','RESEARCHING','REVIEWING','WAITING_FOR_NAWAF'].includes(t.status)).forEach(t=>syncOfficeForTask(t,s))}
function boot(){renderBadge();decorateTasks();decorateTaskModal();heartbeat()}
window.addEventListener('nawaf:state-updated',()=>{renderBadge();decorateTasks()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(heartbeat,250)});setInterval(boot,1000);window.NawafAgents={runTask,runNext,health,pull};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();
